-- stmt
-- Who decided what, and from which state to which. The supervision seam of the
-- audit store.
--
-- **This table is the typed half of a record whose other half is an audit
-- event, and the two are written in one transaction.** jetsapi.agent_audit
-- carries an `approval` event type and always has, which is what makes
-- the decision tamper-evident: hash-chained, append-only, ordered within its
-- run. What it cannot carry is structure. Its columns are actor and tier; the
-- subject, the two states and the rationale would live in `payload` jsonb,
-- where `from_state` is unconstrained while change_proposal.approval_state
-- three tables up is CHECKed against the same vocabulary. Recording a
-- transition less strictly than the state it produces is the asymmetry this
-- table removes.
--
-- Like agent_run and unlike agent_audit it is not append-only by trigger, and
-- unlike agent_run it is never updated either: a decision is a new row
-- referencing the same subject, which is the entity's own docstring and the
-- reason outcomes are appended rather than mutated.
--
-- run_ref is the originating run, not the approver's session. A proposal is
-- approved after the run that produced it has ended, so this table and the
-- chain both grow past agent_run.ended_at. That is intended: the approval is
-- part of the run's story, and there is no seal to violate - nothing closes a
-- chain.
CREATE TABLE IF NOT EXISTS jetsapi.approval_event (
  approval_event_id                text PRIMARY KEY,
  run_ref                          text NOT NULL,
  subject_ref                      text NOT NULL,
  from_state                       text NOT NULL,
  to_state                         text NOT NULL,
  actor                            text NOT NULL,
  tier_at_event                    text NOT NULL,
  decided_at                       timestamp with time zone NOT NULL,
  decision_rationale               text,
  CONSTRAINT approval_event_from_state_ck CHECK (from_state IN ('draft', 'validated', 'agent_reviewed', 'awaiting_human_approval', 'approved', 'approved_with_modification', 'rejected', 'superseded', 'deployed')),
  CONSTRAINT approval_event_to_state_ck CHECK (to_state IN ('draft', 'validated', 'agent_reviewed', 'awaiting_human_approval', 'approved', 'approved_with_modification', 'rejected', 'superseded', 'deployed')),
  CONSTRAINT approval_event_tier_ck CHECK (tier_at_event IN ('T0', 'T1', 'T2', 'T3', 'T4'))
);
-- stmt
ALTER TABLE jetsapi.approval_event ADD COLUMN IF NOT EXISTS run_ref text NOT NULL;
-- stmt
ALTER TABLE jetsapi.approval_event ADD COLUMN IF NOT EXISTS subject_ref text NOT NULL;
-- stmt
ALTER TABLE jetsapi.approval_event ADD COLUMN IF NOT EXISTS from_state text NOT NULL;
-- stmt
ALTER TABLE jetsapi.approval_event ADD COLUMN IF NOT EXISTS to_state text NOT NULL;
-- stmt
ALTER TABLE jetsapi.approval_event ADD COLUMN IF NOT EXISTS actor text NOT NULL;
-- stmt
ALTER TABLE jetsapi.approval_event ADD COLUMN IF NOT EXISTS tier_at_event text NOT NULL;
-- stmt
ALTER TABLE jetsapi.approval_event ADD COLUMN IF NOT EXISTS decided_at timestamp with time zone NOT NULL;
-- stmt
ALTER TABLE jetsapi.approval_event ADD COLUMN IF NOT EXISTS decision_rationale text;
-- stmt
-- Answering "who approved proposal X" and "what happened to it" without a
-- jsonb scan is the whole reason the typed half exists.
CREATE INDEX IF NOT EXISTS approval_event_subject_idx
  ON jetsapi.approval_event (subject_ref, decided_at);
-- stmt
CREATE INDEX IF NOT EXISTS approval_event_run_idx
  ON jetsapi.approval_event (run_ref);
-- stmt
-- What a deterministic detector observed.
--
-- **This table is here because `$as_table` is not persistence.** The Anomaly entity
-- carries jr_as_table = True, which makes it a table in the JetRules domain model and
-- says nothing about Postgres. Exactly that confusion once left agent_run and
-- change_proposal modelled and unwritable, and was resolved by emitting both from this
-- generator. Anomaly is the third application of that resolution, and the first where
-- the two halves were done in one change.
--
-- Unlike agent_audit this table is not append-only by trigger, and unlike agent_run it
-- is not updated: a detector's observation is a fact about one run at one instant.
-- Re-running a detector over the same worker produces a second row, and that is
-- intended - the anomaly_detector_ref column is what tells two generations of a
-- detector apart.
--
-- The detector rows fix what each column can hold; three of the schema's own required
-- properties are nullable here because four of the six derivable rows are within-run
-- predicates with no range and no magnitude. The CHECK constraints carry the three
-- vocabularies, two of which extend the proposal's Anomaly schema with the rows and
-- grains JetStore's execution record actually has.
--
-- anomaly_confounders is a text[] with a containment CHECK rather than a child table.
-- The list is small, closed and read whole, which is the same argument the array
-- columns above rest on; `<@` is what constrains an array against a vocabulary, since
-- a column CHECK cannot reach inside one element at a time.
CREATE TABLE IF NOT EXISTS jetsapi.anomaly (
  anomaly_id                       text PRIMARY KEY,
  detected_at                      timestamp with time zone NOT NULL,
  anomaly_session_id               text NOT NULL,
  anomaly_subject_type             text NOT NULL,
  anomaly_subject_ref              text NOT NULL,
  anomaly_signal_type              text NOT NULL,
  anomaly_observed_value           text NOT NULL,
  anomaly_expected_min             text,
  anomaly_expected_max             text,
  anomaly_expected_basis           text NOT NULL,
  anomaly_deviation_magnitude      double precision,
  anomaly_confounders              text[] NOT NULL,
  anomaly_detector_ref             text NOT NULL,
  CONSTRAINT anomaly_signal_type_ck CHECK (anomaly_signal_type IN ('volume', 'freshness', 'schema', 'distribution', 'rule_breach', 'cost', 'duration', 'rejection_rate', 'cardinality', 'referential', 'step_regression', 'worker_stall', 'arrival')),
  CONSTRAINT anomaly_subject_type_ck CHECK (anomaly_subject_type IN ('feed', 'pipeline', 'stage', 'run', 'table', 'column', 'worker', 'edge')),
  CONSTRAINT anomaly_confounders_ck
             CHECK (anomaly_confounders <@ ARRAY['parse_errors_only', 'parquet_input', 'on_error_drop', 'max_input_count', 'sampling_cap', 'device_writer_output', 'merge_row_count_unknown', 'step_label_ambiguous', 'stall_cause_unknown', 'cross_step_join_unavailable', 'history_truncated', 'no_physical_location', 'stage_prefix_reused', 'location_aimed_not_reached']::text[])
);
-- stmt
ALTER TABLE jetsapi.anomaly ADD COLUMN IF NOT EXISTS detected_at timestamp with time zone NOT NULL;
-- stmt
ALTER TABLE jetsapi.anomaly ADD COLUMN IF NOT EXISTS anomaly_session_id text NOT NULL;
-- stmt
ALTER TABLE jetsapi.anomaly ADD COLUMN IF NOT EXISTS anomaly_subject_type text NOT NULL;
-- stmt
ALTER TABLE jetsapi.anomaly ADD COLUMN IF NOT EXISTS anomaly_subject_ref text NOT NULL;
-- stmt
ALTER TABLE jetsapi.anomaly ADD COLUMN IF NOT EXISTS anomaly_signal_type text NOT NULL;
-- stmt
ALTER TABLE jetsapi.anomaly ADD COLUMN IF NOT EXISTS anomaly_observed_value text NOT NULL;
-- stmt
ALTER TABLE jetsapi.anomaly ADD COLUMN IF NOT EXISTS anomaly_expected_min text;
-- stmt
