-- stmt
ALTER TABLE jetsapi.anomaly ADD COLUMN IF NOT EXISTS anomaly_detector_ref text NOT NULL;
-- stmt
-- "Which anomalies did this run produce", which is how a triage step reaches them, and
-- "what has this detector been saying lately", which is how a false-positive rate is
-- read off. Neither is answerable from the primary key.
CREATE INDEX IF NOT EXISTS anomaly_session_idx
  ON jetsapi.anomaly (anomaly_session_id, detected_at);
-- stmt
CREATE INDEX IF NOT EXISTS anomaly_detector_idx
  ON jetsapi.anomaly (anomaly_detector_ref, detected_at);
-- stmt
-- What triage concluded.
--
-- **Two taxonomies, on purpose.** incident_locus is where in the record the evidence
-- sits -- nine positions in a run's execution record and two in a feed's deliveries,
-- each a predicate over jetsapi with no free-text parsing -- and classification is what produced the failure, the proposal's own ten.
-- The triage design's reading is that the record supports the first and does not
-- support the second below the level of a hypothesis: three of the ten classes have no
-- substrate in JetStore at all and four are evidenced only coarsely. Carrying both is
-- that design's recommendation, because pruning an imported model unilaterally is not
-- this model's call. Read incident_locus as evidence and classification as a claim; a
-- report that aggregates accuracy over both silently rescopes what it measures.
--
-- **The grain is the session and that is a finding, not a default.** Seven tables can
-- carry evidence for an incident and session_id is the only key all seven share,
-- so an incident identified below the session is one whose evidence set cannot
-- be assembled by a join. incident_step_ref and incident_shard_ref are nullable
-- because localisation is a property of an incident and not its identity: four of the
-- nine run loci supply no step at all, and neither delivery locus does. An incident that sets incident_step_ref should
-- carry step_label_ambiguous, cpipes_step_id being a stage location rather than a step
-- identity -- which is why incident_confounders reuses the detector's vocabulary
-- rather than opening a second one that would not compare.
--
-- **incident_step_confounder_ck is the one cross-column rule in this file, and it is an
-- invariant rather than a convention.** An incident that names a step must carry
-- step_label_ambiguous, and the reason does not depend on which step it is:
-- cpipes_step_id is a stage location, so *any* incident naming one inherits the
-- ambiguity. That makes it checkable, and a requirement that is checkable and left to
-- prose is a requirement that goes quiet the first time nobody re-reads the design. The
-- alternative -- leave it to the triage classifier -- was rejected for that reason and
-- not for a technical one.
--
-- **incident_run_ref is a governance column and not a localisation one.**
-- Every other reference here says where in the execution record the incident sits; this
-- one says which AgentRun raised it, and it exists because jetsapi.agent_audit is keyed
-- on an AgentRun by construction. Before it, a transition on an incident reached
-- the hash chain only when its own caller named a run -- which put a person's correction
-- of a classification on the unchained side and an agent's own reclassification on the
-- chained one, inverting the property a governance record is for.
-- RecordIncidentTransition reads this column inside the write and uses it when the
-- caller supplies none. It is nullable because a deterministic triage step is not an
-- AgentRun, so the residue is *incidents nothing agentic raised*, uniform across actors
-- rather than aimed at humans. No foreign key, on approval_event.run_ref's
-- precedent.
--
-- Note what is NOT a column: hypotheses. The domain model declares it as an object
-- property and JetRules traverses it in working memory; in Postgres the same
-- relationship is jetsapi.hypothesis.hypothesis_incident_ref, and two writable
-- statements of one fact is how they drift. The emitter drops the column by rule
-- rather than by hand -- see _table_columns.
--
-- Like anomaly and unlike agent_audit this table is not append-only by trigger, and
-- unlike anomaly it IS updated: status walks the proposal's incident state machine, so an
-- incident row is mutable state and the audit chain is the record of how it moved.
CREATE TABLE IF NOT EXISTS jetsapi.incident (
  incident_id                      text PRIMARY KEY,
  incident_session_id              text NOT NULL,
  incident_run_ref                 text,
  incident_detected_at             timestamp with time zone NOT NULL,
  incident_locus                   text NOT NULL,
  classification                   text,
  severity                         text NOT NULL,
  status                           text NOT NULL,
  incident_step_ref                text,
  incident_shard_ref               bigint,
  incident_confounders             text[] NOT NULL,
  incident_model_version           text NOT NULL,
  incident_error_code              text,
  incident_client                  text,
  incident_process_name            text,
  incident_anchor_start_time       timestamp with time zone,
  incident_feed                    text,
  CONSTRAINT incident_locus_ck CHECK (incident_locus IN ('run_not_started', 'step_never_started', 'worker_not_terminated', 'worker_failed', 'sink_failed_under_completed_worker', 'rows_lost_silently', 'per_record_failures_reported', 'per_record_failures_unreportable', 'written_not_arrived', 'delivery_overdue', 'delivery_departs_profile', 'job_failed')),
  CONSTRAINT incident_classification_ck
             CHECK (classification IS NULL OR classification IN ('source_delivery_failure', 'source_content_change', 'transport_failure', 'parse_failure', 'validation_breach', 'transformation_defect', 'infrastructure_failure', 'dependency_failure', 'capacity_or_cost_deviation', 'benign_variation')),
  CONSTRAINT incident_severity_ck CHECK (severity IN ('info', 'low', 'medium', 'high', 'critical')),
  CONSTRAINT incident_status_ck CHECK (status IN ('detected', 'triaged', 'diagnosed', 'remediation_proposed', 'awaiting_approval', 'remediating', 'resolved', 'verified', 'closed', 'reclassified', 'suppressed_as_benign')),
  CONSTRAINT incident_confounders_ck
             CHECK (incident_confounders <@ ARRAY['parse_errors_only', 'parquet_input', 'on_error_drop', 'max_input_count', 'sampling_cap', 'device_writer_output', 'merge_row_count_unknown', 'step_label_ambiguous', 'stall_cause_unknown', 'cross_step_join_unavailable', 'history_truncated', 'no_physical_location', 'stage_prefix_reused', 'location_aimed_not_reached']::text[]),
  CONSTRAINT incident_step_confounder_ck
             CHECK (incident_step_ref IS NULL
                    OR 'step_label_ambiguous' = ANY (incident_confounders))
);
-- stmt
ALTER TABLE jetsapi.incident ADD COLUMN IF NOT EXISTS incident_session_id text NOT NULL;
-- stmt
ALTER TABLE jetsapi.incident ADD COLUMN IF NOT EXISTS incident_run_ref text;
-- stmt
ALTER TABLE jetsapi.incident ADD COLUMN IF NOT EXISTS incident_detected_at timestamp with time zone NOT NULL;
-- stmt
ALTER TABLE jetsapi.incident ADD COLUMN IF NOT EXISTS incident_locus text NOT NULL;
-- stmt
