-- stmt
-- incident_locus_ck follows incident_locus's vocabulary onto a table created before the
-- vocabulary last changed. See _replaced_vocabulary_check in the emitter.
DO $$
DECLARE
  admitted text[];
BEGIN
  SELECT array(SELECT m[1]
                 FROM regexp_matches(pg_get_constraintdef(c.oid), '''([a-z0-9_]+)''', 'g') AS m)
    INTO admitted
    FROM pg_constraint c
   WHERE c.conrelid = 'jetsapi.incident'::regclass AND c.conname = 'incident_locus_ck';
  IF admitted IS NULL
     OR NOT (admitted @> ARRAY['run_not_started', 'step_never_started', 'worker_not_terminated', 'worker_failed', 'sink_failed_under_completed_worker', 'rows_lost_silently', 'per_record_failures_reported', 'per_record_failures_unreportable', 'written_not_arrived', 'delivery_overdue', 'delivery_departs_profile', 'job_failed']::text[]
             AND admitted <@ ARRAY['run_not_started', 'step_never_started', 'worker_not_terminated', 'worker_failed', 'sink_failed_under_completed_worker', 'rows_lost_silently', 'per_record_failures_reported', 'per_record_failures_unreportable', 'written_not_arrived', 'delivery_overdue', 'delivery_departs_profile', 'job_failed']::text[]) THEN
    ALTER TABLE jetsapi.incident
      DROP CONSTRAINT IF EXISTS incident_locus_ck,
      ADD CONSTRAINT incident_locus_ck CHECK (incident_locus IN ('run_not_started', 'step_never_started', 'worker_not_terminated', 'worker_failed', 'sink_failed_under_completed_worker', 'rows_lost_silently', 'per_record_failures_reported', 'per_record_failures_unreportable', 'written_not_arrived', 'delivery_overdue', 'delivery_departs_profile', 'job_failed'));
  END IF;
END $$;
-- stmt
-- "What happened in this run", which is how an operator reaches an incident from a
-- session id, and "what is open", which is how a supervision screen lists them.
CREATE INDEX IF NOT EXISTS incident_session_idx
  ON jetsapi.incident (incident_session_id, incident_detected_at);
-- stmt
CREATE INDEX IF NOT EXISTS incident_status_idx
  ON jetsapi.incident (status, incident_detected_at);
-- stmt
-- "Which incidents stand for this run condition", which is how a run finding is placed:
-- a run condition's incidents are found by their key (client, process name, locus and
-- error code) and their position (the anchor run's start time), never by their session,
-- so that an incident whose first run was deleted is still its condition's. Partial,
-- because only an incident at a run locus written with run conditions carries a key.
CREATE INDEX IF NOT EXISTS incident_run_condition_idx
  ON jetsapi.incident (incident_client, incident_process_name, incident_locus, incident_anchor_start_time)
  WHERE incident_client IS NOT NULL;
-- stmt
-- "Which incidents stand for this feed condition", the same lookup for a delivery locus: a
-- feed condition's incidents are found by their key (the feed and the locus) and their
-- position (the anchor delivery's arrival, its session id read as a time), so that an
-- incident whose first delivery was deleted with its session is still its condition's.
-- Partial, because only a feed incident written with keys carries one; one written before
-- is found by its session, as every feed incident was.
CREATE INDEX IF NOT EXISTS incident_feed_condition_idx
  ON jetsapi.incident (incident_feed, incident_locus, incident_anchor_start_time)
  WHERE incident_feed IS NOT NULL;
-- stmt
-- What triage found at each run locus of each run it classified, and for each error code
-- at per_record_failures_reported: the verdict a run condition is read from.
--
-- **A run's findings are otherwise computed and never stored**: the shadow writer writes
-- an incident for a present finding and nothing for an absent, quiet or not-evaluable
-- one, and a run that joins a condition has no incident of its own. A run condition ends
-- at a run whose finding is absent, and only a stored verdict can say which runs those
-- were. So the writer stores every run locus's verdict for every run it classifies. It
-- stores a verdict, not a join: which incident a run belongs to is derived on every read.
--
-- The key is (session_id, locus, error_code). error_code is '' at the eight run loci that
-- have no code. At per_record_failures_reported the row with error_code '' is the locus
-- as a whole (present, absent or not_evaluable), and there is one more row per code the
-- run's process_errors rows were given, present or quiet. **A code with no row of its own
-- on a run whose '' row is present or absent is absent for that run**; a run whose '' row
-- is not_evaluable is not evaluable for every code; a run with no row is one triage never
-- classified, which a condition skips.
--
-- **Added and upgraded, never retracted.** A row is inserted on a run's first
-- classification and replaced only by a later verdict that says more (not_evaluable, then
-- absent, then quiet, then present), so a classification that can see less, a purged
-- worker record or a dropped table, cannot turn a condition's member into a gap. The rows
-- are deleted with their session, by jets/sessionpurge, as the run's process_errors are:
-- a deleted run is no position of any condition, so nothing reads its verdict.
--
-- stored_rows is the code's stored rows in the run, a lower bound because an operator
-- instance stops storing rows at its max_error_count; null on the '' rows.
CREATE TABLE IF NOT EXISTS jetsapi.run_finding (
  session_id                       text NOT NULL,
  locus                            text NOT NULL,
  error_code                       text NOT NULL DEFAULT '',
  verdict                          text NOT NULL,
  stored_rows                      bigint,
  classifier_ref                   text NOT NULL,
  classified_at                    timestamp with time zone NOT NULL,
  PRIMARY KEY (session_id, locus, error_code),
  CONSTRAINT run_finding_locus_ck CHECK (locus IN ('run_not_started', 'step_never_started', 'worker_not_terminated', 'worker_failed', 'sink_failed_under_completed_worker', 'rows_lost_silently', 'per_record_failures_reported', 'per_record_failures_unreportable', 'written_not_arrived', 'delivery_overdue', 'delivery_departs_profile', 'job_failed')),
  CONSTRAINT run_finding_verdict_ck CHECK (verdict IN ('present', 'quiet', 'absent', 'not_evaluable')),
  CONSTRAINT run_finding_code_ck
             CHECK (error_code = '' OR locus = 'per_record_failures_reported'),
  CONSTRAINT run_finding_quiet_ck
             CHECK (verdict <> 'quiet' OR error_code <> '')
);
-- stmt
-- run_finding_locus_ck follows locus's vocabulary onto a table created before the
-- vocabulary last changed. See _replaced_vocabulary_check in the emitter.
DO $$
DECLARE
  admitted text[];
BEGIN
  SELECT array(SELECT m[1]
                 FROM regexp_matches(pg_get_constraintdef(c.oid), '''([a-z0-9_]+)''', 'g') AS m)
    INTO admitted
    FROM pg_constraint c
   WHERE c.conrelid = 'jetsapi.run_finding'::regclass AND c.conname = 'run_finding_locus_ck';
  IF admitted IS NULL
     OR NOT (admitted @> ARRAY['run_not_started', 'step_never_started', 'worker_not_terminated', 'worker_failed', 'sink_failed_under_completed_worker', 'rows_lost_silently', 'per_record_failures_reported', 'per_record_failures_unreportable', 'written_not_arrived', 'delivery_overdue', 'delivery_departs_profile', 'job_failed']::text[]
             AND admitted <@ ARRAY['run_not_started', 'step_never_started', 'worker_not_terminated', 'worker_failed', 'sink_failed_under_completed_worker', 'rows_lost_silently', 'per_record_failures_reported', 'per_record_failures_unreportable', 'written_not_arrived', 'delivery_overdue', 'delivery_departs_profile', 'job_failed']::text[]) THEN
    ALTER TABLE jetsapi.run_finding
      DROP CONSTRAINT IF EXISTS run_finding_locus_ck,
      ADD CONSTRAINT run_finding_locus_ck CHECK (locus IN ('run_not_started', 'step_never_started', 'worker_not_terminated', 'worker_failed', 'sink_failed_under_completed_worker', 'rows_lost_silently', 'per_record_failures_reported', 'per_record_failures_unreportable', 'written_not_arrived', 'delivery_overdue', 'delivery_departs_profile', 'job_failed'));
  END IF;
END $$;
-- stmt
-- One summary of one delivery of a profiled feed, which the five claim-set checks judge
-- from, so they still judge once the claim rows are gone. Written by feed_detect before it
-- judges (jets/agentic/observe/feed_claimset_summary.go, which says what each column holds
-- and how), and later by a pipeline operator that computes the same row from its records.
-- **No column holds a member, a claim key, an amount, or a date of a delivery with fewer
-- distinct members than the run's minimum**: the dates of such a delivery are the first of
-- their month, and a delivery with fewer distinct keys than that minimum keeps no
-- fingerprint and no sketch, because the fingerprint of one claim is that claim's hash.
--
-- The key set is hashed by the one rule in jets/keyset: key_fingerprint is the sum of the
-- distinct keys' hashes modulo 2^64, stored as the bigint of the same 64 bits, and
-- key_sketch a HyperLogLog of 2^14 registers packed 6 bits each, 12,288 bytes.
--
-- delivery_session_id is the delivery's registration session, which its anomalies are
-- keyed on; session_id is the session whose rows were read, a pipeline run's as a rule, and
-- the row is deleted with it by both deletion paths, not with the session's table data.
-- key_columns, service_date_column and member_column are the declaration the row was
-- computed under, so a profile that changes them makes the row stale rather than wrong.
-- lag_exceeds and out_of_span_count are decided on the exact days against the declaration
-- named beside them, at summary time.
CREATE TABLE IF NOT EXISTS jetsapi.claim_set_summary (
  table_name                       text NOT NULL,
  delivery_session_id              text NOT NULL,
  session_id                       text NOT NULL,
  client                           text NOT NULL,
  summary_version                  integer NOT NULL,
  summarised_at                    timestamp with time zone NOT NULL,
  key_columns                      text[] NOT NULL,
  service_date_column              text NOT NULL,
  member_column                    text NOT NULL,
  row_count                        bigint NOT NULL,
  distinct_key_count               bigint NOT NULL,
  member_count                     bigint NOT NULL,
  dated_row_count                  bigint NOT NULL,
  newest_service_date              date,
  oldest_service_date              date,
  dates_in_months                  boolean NOT NULL,
  span_days                        bigint,
  lag_exceeds                      boolean,
  lag_declared_days                integer,
  out_of_span_count                bigint,
  span_declared_days               integer,
  service_date_histogram           jsonb,
  present_counts                   jsonb NOT NULL,
  key_fingerprint                  bigint,
  key_sketch                       bytea,
  PRIMARY KEY (table_name, delivery_session_id),
  CONSTRAINT claim_set_summary_sketch_ck
             CHECK (key_sketch IS NULL OR octet_length(key_sketch) = 12288)
);
-- stmt
CREATE INDEX IF NOT EXISTS claim_set_summary_session_idx
  ON jetsapi.claim_set_summary (session_id);
-- stmt
-- One ranked causal hypothesis for an incident, emitted with the table above.
--
-- **contradicting_evidence is NOT NULL because the model marks it required, and that
-- is the whole point of the column.** The proposal calls it a calibration control:
-- an agent that can omit the evidence against its own hypothesis will. That side has a
-- substrate already built -- AnomalyConfounder's fourteen members are the record's own
-- statement of what a detector could not rule out -- and EvidenceSource gained
-- detector_confounder so a hypothesis can name it. An
-- empty array is the honest value where the agent asserts none exists; null is not.
--
-- Both evidence columns are jsonb rather than text[]. Evidence is a value object with
-- three fields and no table of its own (it is a JetsaValue, $as_table = false, on the
-- jets:State precedent), so it inlines; text[] is what the emitter's unmapped-type
-- fall-through would have produced, and it would have stored three fields as one
-- opaque string per item. That is the silent text widening reaching a composite, and
-- tabling this entity is what exposed it.
--
-- **hypothesis_locus and basis were added deliberately before the first row was
-- written.** The requirement that *a human can read the ranking's basis* was met in
-- what the ranker emits and did not survive the write, because this table had a column
-- for neither.
--
-- hypothesis_locus is constrained by the SAME vocabulary incident_locus is: the CHECK
-- below interpolates the one 'run_not_started', 'step_never_started', 'worker_not_terminated', 'worker_failed', 'sink_failed_under_completed_worker', 'rows_lost_silently', 'per_record_failures_reported', 'per_record_failures_unreportable', 'written_not_arrived', 'delivery_overdue', 'delivery_departs_profile', 'job_failed' the emitter builds from M.IncidentLocus, so there is
-- no second list to drift. It is required because the ranker's headline finding was that
-- 20 of 29 model-generated hypotheses sat at loci triage did not find present -- and
-- without this column a hypothesis raised at an absent locus is indistinguishable in
-- stored data from a sound one, which would persist that failure mode in a form that
-- hides it.
--
-- basis is counts rather than prose: the two evidence lengths and the evidenceability
-- tier the ranker sorts on. A count can be checked against the arrays on
-- the same row and a sentence cannot. It is persisted rather than left to be recomputed
-- because *re-run it* is false twice over: the model arm is not deterministic (16
-- hypotheses on one run and 13 on the next from identical input), and the evidence itself
-- expires on two clocks the row does not share -- RETENTION_DAYS with no default, and six
-- months hard-coded on the run header.
--
-- hypothesis_incident_ref has no foreign key, on approval_event.run_ref's precedent:
-- these tables are installed by one call and purged by session, and a constraint here
-- would order inserts that shadow mode has no reason to order. The index is what the
-- question actually needs.
CREATE TABLE IF NOT EXISTS jetsapi.hypothesis (
  hypothesis_id                    text PRIMARY KEY,
  hypothesis_incident_ref          text NOT NULL,
  cause                            text NOT NULL,
  cause_category                   text,
  confidence                       double precision NOT NULL,
  rank                             bigint NOT NULL,
  supporting_evidence              jsonb NOT NULL,
  contradicting_evidence           jsonb NOT NULL,
  hypothesis_locus                 text NOT NULL,
  basis                            jsonb NOT NULL,
  CONSTRAINT hypothesis_cause_category_ck
             CHECK (cause_category IS NULL OR cause_category IN ('source_delivery_failure', 'source_content_change', 'transport_failure', 'parse_failure', 'validation_breach', 'transformation_defect', 'infrastructure_failure', 'dependency_failure', 'capacity_or_cost_deviation', 'benign_variation')),
  CONSTRAINT hypothesis_locus_ck CHECK (hypothesis_locus IN ('run_not_started', 'step_never_started', 'worker_not_terminated', 'worker_failed', 'sink_failed_under_completed_worker', 'rows_lost_silently', 'per_record_failures_reported', 'per_record_failures_unreportable', 'written_not_arrived', 'delivery_overdue', 'delivery_departs_profile', 'job_failed'))
);
-- stmt
ALTER TABLE jetsapi.hypothesis ADD COLUMN IF NOT EXISTS hypothesis_incident_ref text NOT NULL;
-- stmt
ALTER TABLE jetsapi.hypothesis ADD COLUMN IF NOT EXISTS cause text NOT NULL;
-- stmt
ALTER TABLE jetsapi.hypothesis ADD COLUMN IF NOT EXISTS cause_category text;
-- stmt
ALTER TABLE jetsapi.hypothesis ADD COLUMN IF NOT EXISTS confidence double precision NOT NULL;
-- stmt
ALTER TABLE jetsapi.hypothesis ADD COLUMN IF NOT EXISTS rank bigint NOT NULL;
-- stmt
ALTER TABLE jetsapi.hypothesis ADD COLUMN IF NOT EXISTS supporting_evidence jsonb NOT NULL;
-- stmt
ALTER TABLE jetsapi.hypothesis ADD COLUMN IF NOT EXISTS contradicting_evidence jsonb NOT NULL;
-- stmt
ALTER TABLE jetsapi.hypothesis ADD COLUMN IF NOT EXISTS hypothesis_locus text NOT NULL;
-- stmt
ALTER TABLE jetsapi.hypothesis ADD COLUMN IF NOT EXISTS basis jsonb NOT NULL;
-- stmt
-- hypothesis_locus_ck follows hypothesis_locus's vocabulary onto a table created before the
-- vocabulary last changed. See _replaced_vocabulary_check in the emitter.
DO $$
DECLARE
  admitted text[];
BEGIN
  SELECT array(SELECT m[1]
                 FROM regexp_matches(pg_get_constraintdef(c.oid), '''([a-z0-9_]+)''', 'g') AS m)
    INTO admitted
    FROM pg_constraint c
   WHERE c.conrelid = 'jetsapi.hypothesis'::regclass AND c.conname = 'hypothesis_locus_ck';
  IF admitted IS NULL
     OR NOT (admitted @> ARRAY['run_not_started', 'step_never_started', 'worker_not_terminated', 'worker_failed', 'sink_failed_under_completed_worker', 'rows_lost_silently', 'per_record_failures_reported', 'per_record_failures_unreportable', 'written_not_arrived', 'delivery_overdue', 'delivery_departs_profile', 'job_failed']::text[]
             AND admitted <@ ARRAY['run_not_started', 'step_never_started', 'worker_not_terminated', 'worker_failed', 'sink_failed_under_completed_worker', 'rows_lost_silently', 'per_record_failures_reported', 'per_record_failures_unreportable', 'written_not_arrived', 'delivery_overdue', 'delivery_departs_profile', 'job_failed']::text[]) THEN
    ALTER TABLE jetsapi.hypothesis
      DROP CONSTRAINT IF EXISTS hypothesis_locus_ck,
      ADD CONSTRAINT hypothesis_locus_ck CHECK (hypothesis_locus IN ('run_not_started', 'step_never_started', 'worker_not_terminated', 'worker_failed', 'sink_failed_under_completed_worker', 'rows_lost_silently', 'per_record_failures_reported', 'per_record_failures_unreportable', 'written_not_arrived', 'delivery_overdue', 'delivery_departs_profile', 'job_failed'));
  END IF;
END $$;
-- stmt
-- "The ranking for this incident, in order", which is the only way a human reads
-- hypotheses and is not answerable from the primary key.
CREATE INDEX IF NOT EXISTS hypothesis_incident_idx
  ON jetsapi.hypothesis (hypothesis_incident_ref, rank);
-- stmt
-- A proposed corrective action -- **with no executor, and nothing yet writes a row.**
-- Nothing acts; what the table buys is that an autonomy gate has a subject. Autonomy
-- tiers are recorded, trustworthy and gate nothing, and autonomy_tier_required is the one property in the model that names the
-- authority an *action* needs rather than the authority a run had.
--
-- **remediation_reversibility_ck is the proposal's own validator rule and not a local
-- policy.** The proposal states it: "reversibility: irreversible is rejected at schema
-- level. No irreversible remediation may be persisted at any tier." So the Reversibility vocabulary carries three members -- the rule is about the
-- third -- and this table accepts two. The excluded value is read off the enum rather
-- than spelled here, so a rename moves the rule instead of quietly widening it, which
-- is the same mechanism as incident_step_confounder_ck above.
--
-- **The cost of that CHECK is worth naming beside it.** An agent that concludes the
-- only available correction is irreversible cannot record the conclusion; it can only
-- decline to propose. The record then shows nothing where a refusal happened, which is
-- a gap a supervision screen cannot display and a metric cannot count. Enforcing the
-- proposal's own rule is still the right call -- the alternative is a table that
-- accepts a row the proposal forbids -- but it is a trade rather than a free guard.
--
-- Four of the proposal's nine required Remediation properties are absent: action_type,
-- proposed_by, rationale and blast_radius. The first is the executor's dispatch key and
-- a tier rule keyed on it would be inventing the autonomy gate here; the others are read by a
-- screen that does not write yet. approver and approved_at are absent for a different
-- reason -- ApprovalEvent.subject_ref is documented as "the Remediation or ChangeProposal
-- being decided", so they are already a row in jetsapi.approval_event, and inlining them
-- would be two writable statements of one fact.
CREATE TABLE IF NOT EXISTS jetsapi.remediation (
  remediation_id                   text PRIMARY KEY,
  incident_ref                     text NOT NULL,
  autonomy_tier_required           text NOT NULL,
  reversibility                    text NOT NULL,
  remediation_approval_state       text NOT NULL,
  CONSTRAINT remediation_tier_ck CHECK (autonomy_tier_required IN ('T0', 'T1', 'T2', 'T3', 'T4')),
  CONSTRAINT remediation_approval_state_ck
             CHECK (remediation_approval_state IN ('draft', 'validated', 'agent_reviewed', 'awaiting_human_approval', 'approved', 'approved_with_modification', 'rejected', 'superseded', 'deployed')),
  -- The proposal's rule: 'irreversible' is a member of the vocabulary and is not
  -- a persistable value.
  CONSTRAINT remediation_reversibility_ck
             CHECK (reversibility IN ('fully_reversible', 'reversible_with_backfill'))
);
-- stmt
ALTER TABLE jetsapi.remediation ADD COLUMN IF NOT EXISTS incident_ref text NOT NULL;
-- stmt
ALTER TABLE jetsapi.remediation ADD COLUMN IF NOT EXISTS autonomy_tier_required text NOT NULL;
-- stmt
ALTER TABLE jetsapi.remediation ADD COLUMN IF NOT EXISTS reversibility text NOT NULL;
-- stmt
ALTER TABLE jetsapi.remediation ADD COLUMN IF NOT EXISTS remediation_approval_state text NOT NULL;
-- stmt
-- "What has been proposed for this incident", which is how a supervision screen reaches
-- a remediation and is not answerable from the primary key.
CREATE INDEX IF NOT EXISTS remediation_incident_idx
  ON jetsapi.remediation (incident_ref, remediation_approval_state);
-- stmt
-- One transition of one incident. The preamble of the proposal's state machines says
-- "Every transition records actor, agent version where applicable, and timestamp" and
-- then draws four machines and no entity to record one. jetsapi.approval_event is that
-- entity for ChangeProposal; this is it for Incident.
--
-- **The reason it is owed is a labelled population rather than an audit trail.** Three
-- of IncidentStatus's eleven values are adjudications rather than progress --
-- reclassified, verified, suppressed_as_benign -- so the lifecycle already carried the
-- verdicts the four label-bearing metrics need. What it did not carry is
-- who reached them, and a label the measured system may have written is not a label.
--
-- **event_actor_kind is a column and not a spelling convention**, which is the one place
-- this table departs from approval_event's shape on purpose. That table's actor is "a
-- user_email or an agent identity" and leaves the two apart by the shape of the string;
-- a metric that partitions human corrections from the system's own reclassifications
-- cannot rest its denominator on a regular expression over an email address.
--
-- **classification_before and classification_after travel on the event because the
-- incident row is mutable.** A second correction overwrites the first, so the pairing
-- the metrics score would be gone. RecordIncidentTransition reads classification_before
-- out of the row inside the same statement that moves it, rather than accepting it from
-- the caller: the party being measured does not state what it is measured against.
--
-- incident_event_reclassified_ck is the proposal's own sentence -- "reclassified returns
-- to triaged with a new classification and a recorded reason" -- as a cross-column rule.
-- It is the second such CHECK in this file and it fires on the same argument as the
-- first: a requirement that is checkable and left in prose goes quiet the first time
-- nobody re-reads the appendix.
--
-- event_run_ref is nullable and that is the table's one stated weakness. agent_audit's
-- run_id is an AgentRun's key, and neither a human at a screen nor a deterministic
-- triage step is an AgentRun. RecordIncidentTransition falls back to the incident's
-- incident_run_ref when the caller names no run; a transition on an incident nothing
-- agentic raised is durable and attributable here and is not in the hash chain.
--
-- Like incident and unlike agent_audit this table has no append-only trigger, and like
-- approval_event it is never updated: a further transition is a further row.
CREATE TABLE IF NOT EXISTS jetsapi.incident_event (
  incident_event_id                text PRIMARY KEY,
  event_incident_ref               text NOT NULL,
  from_status                      text NOT NULL,
  to_status                        text NOT NULL,
  event_actor                      text NOT NULL,
  event_actor_kind                 text NOT NULL,
  transitioned_at                  timestamp with time zone NOT NULL,
  event_run_ref                    text,
  classification_before            text,
  classification_after             text,
  transition_rationale             text,
  CONSTRAINT incident_event_from_status_ck CHECK (from_status IN ('detected', 'triaged', 'diagnosed', 'remediation_proposed', 'awaiting_approval', 'remediating', 'resolved', 'verified', 'closed', 'reclassified', 'suppressed_as_benign')),
  CONSTRAINT incident_event_to_status_ck CHECK (to_status IN ('detected', 'triaged', 'diagnosed', 'remediation_proposed', 'awaiting_approval', 'remediating', 'resolved', 'verified', 'closed', 'reclassified', 'suppressed_as_benign')),
  CONSTRAINT incident_event_actor_kind_ck CHECK (event_actor_kind IN ('human', 'agent')),
  CONSTRAINT incident_event_classification_before_ck
             CHECK (classification_before IS NULL
                    OR classification_before IN ('source_delivery_failure', 'source_content_change', 'transport_failure', 'parse_failure', 'validation_breach', 'transformation_defect', 'infrastructure_failure', 'dependency_failure', 'capacity_or_cost_deviation', 'benign_variation')),
  CONSTRAINT incident_event_classification_after_ck
             CHECK (classification_after IS NULL
                    OR classification_after IN ('source_delivery_failure', 'source_content_change', 'transport_failure', 'parse_failure', 'validation_breach', 'transformation_defect', 'infrastructure_failure', 'dependency_failure', 'capacity_or_cost_deviation', 'benign_variation')),
  CONSTRAINT incident_event_reclassified_ck
             CHECK (to_status <> 'reclassified'
                    OR (classification_after IS NOT NULL
                        AND transition_rationale IS NOT NULL))
);
-- stmt
ALTER TABLE jetsapi.incident_event ADD COLUMN IF NOT EXISTS event_incident_ref text NOT NULL;
-- stmt
ALTER TABLE jetsapi.incident_event ADD COLUMN IF NOT EXISTS from_status text NOT NULL;
-- stmt
ALTER TABLE jetsapi.incident_event ADD COLUMN IF NOT EXISTS to_status text NOT NULL;
-- stmt
ALTER TABLE jetsapi.incident_event ADD COLUMN IF NOT EXISTS event_actor text NOT NULL;
-- stmt
ALTER TABLE jetsapi.incident_event ADD COLUMN IF NOT EXISTS event_actor_kind text NOT NULL;
-- stmt
ALTER TABLE jetsapi.incident_event ADD COLUMN IF NOT EXISTS transitioned_at timestamp with time zone NOT NULL;
-- stmt
ALTER TABLE jetsapi.incident_event ADD COLUMN IF NOT EXISTS event_run_ref text;
-- stmt
ALTER TABLE jetsapi.incident_event ADD COLUMN IF NOT EXISTS classification_before text;
-- stmt
ALTER TABLE jetsapi.incident_event ADD COLUMN IF NOT EXISTS classification_after text;
-- stmt
ALTER TABLE jetsapi.incident_event ADD COLUMN IF NOT EXISTS transition_rationale text;
-- stmt
-- "How did this incident get here, in order", which is the whole point of the table and
-- is not answerable from the primary key.
CREATE INDEX IF NOT EXISTS incident_event_incident_idx
  ON jetsapi.incident_event (event_incident_ref, transitioned_at);
-- stmt
-- "Which verdicts did people reach, and when" -- the query a labelled population is
-- counted with. Partial on the actor kind because the human rows are
-- the scarce ones and the index exists to make counting them cheap.
CREATE INDEX IF NOT EXISTS incident_event_human_verdict_idx
  ON jetsapi.incident_event (to_status, transitioned_at)
  WHERE event_actor_kind = 'human';
